nização."},{"id":7222,"materia":"prev","nivel":4,"enunciado":"O seguro-desemprego é pago:","opcoes":["Com recursos do FAT, pelo Ministério do Trabalho","Pelo INSS, como benefício previdenciário","Pelo empregador, sempre","Pela Caixa, com dinheiro próprio"],"explicacao":"Não é benefício do regime geral do INSS."},{"id":7223,"materia":"prev","nivel":4,"enunciado":"O período de graça é o tempo em que a pessoa:","opcoes":["Mantém a qualidade de segurado mesmo sem contribuir","Recebe o salário em dobro por um período","Fica isenta de imposto","Pode se aposentar mais cedo"],"explicacao":"Art. 15 da Lei 8.213/1991."},{"id":7224,"materia":"trib","nivel":1,"enunciado":"Uma pequena empresa do Simples Nacional paga vários tributos de uma vez:","opcoes":["Numa guia única mensal (DAS)","Em guias separadas para cada imposto","Só no fim do ano","Somente ao município"],"explicacao":"O Simples unifica a arrecadação."},{"id":7225,"materia":"trib","nivel":2,"enunciado":"No IPTU, o sujeito ativo (quem pode cobrar) é:","opcoes":["O município","O proprietário do imóvel","O estado","O inquilino"],"explicacao":"O sujeito passivo é o contribuinte."},{"id":7226,"materia":"trib","nivel":3,"enunciado":"Cobrar IPI alto sobre cigarros para desestimular o consumo é exemplo de tributação:","opcoes":["Extrafiscal","Fiscal pura","Parafiscal","Confiscatória permitida"],"explicacao":"O objetivo principal não é arrecadar."},{"id":7227,"materia":"afo","nivel":2,"enunciado":"As contas do prefeito são julgadas:","opcoes":["Pela Câmara Municipal, com parecer do Tribunal de Contas","Pelo juiz de direito da comarca","Pelo governador","Pelo próprio prefeito"],"explicacao":"Art. 31 da Constituição."},{"id":7228,"materia":"afo","nivel":2,"enunciado":"Comprar computadores para equipar uma escola pública é despesa:","opcoes":["De capital","Corrente","Extraorçamentária","De pessoal"],"explicacao":"Aumenta o patrimônio público com bens duráveis."},{"id":7229,"materia":"cont","nivel":1,"enunciado":"Ao pagar uma dívida com um fornecedor, a empresa:","opcoes":["Diminui o caixa e o passivo","Aumenta o caixa e o passivo","Aumenta o patrimônio líquido","Não altera nada"],"explicacao":"É uma troca entre ativo e passivo."},{"id":7230,"materia":"cont","nivel":2,"enunciado":"Ao receber de um cliente o valor de uma venda feita a prazo:","opcoes":["O caixa aumenta e os valores a receber diminuem","O patrimônio líquido aumenta pelo recebimento","O passivo aumenta","A receita é registrada de novo"],"explicacao":"A receita já foi reconhecida na venda."},{"id":7231,"materia":"cont","nivel":3,"enunciado":"Quando os sócios integralizam capital em dinheiro, a empresa registra:","opcoes":["Aumento do caixa e do capital social","Aumento do caixa e do passivo circulante","Redução do caixa","Uma receita de vendas"],"explicacao":"O PL cresce com o capital investido."},{"id":7232,"materia":"eco","nivel":1,"enunciado":"O Pix, sistema de pagamentos instantâneos, foi criado pelo:","opcoes":["Banco Central do Brasil","Ministério da Fazenda","Banco do Brasil","Congresso Nacional"],"explicacao":"Funciona desde novembro de 2020."},{"id":7233,"materia":"eco","nivel":1,"enunciado":"A alta no preço dos alimentos da cesta básica pesa mais no orçamento das:","opcoes":["Famílias de baixa renda","Famílias mais ricas","Empresas exportadoras","Prefeituras"],"explicacao":"Gastam proporção maior da renda com comida."},{"id":7234,"materia":"eco","nivel":4,"enunciado":"Quando a Selic está em 8,5% ao ano ou menos, a poupança rende:","opcoes":["70% da Selic mais a TR","0,5% ao mês mais a TR","100% do CDI","O mesmo que a inflação"],"explicacao":"Acima disso, rende 0,5% ao mês mais a TR."},{"id":7235,"materia":"aud","nivel":1,"enunciado":"Incluir na folha de pagamento um funcionário que não existe é um exemplo de:","opcoes":["Fraude","Erro de soma","Controle interno","Auditoria"],"explicacao":"O chamado \"funcionário fantasma\"."},{"id":7236,"materia":"dados","nivel":0,"enunciado":"Numa planilha de arrecadação, a função SOMA serve para:","opcoes":["Totalizar os valores","Ordenar os nomes","Mudar a cor das células","Apagar dados"],"explicacao":"Exemplo: =SOMA(B2:B13)."},{"id":7237,"materia":"dados","nivel":2,"enunciado":"Dados registrados mês a mês, como a arrecadação ao longo de 5 anos, formam uma:","opcoes":["Série temporal","Amostra estratificada","Tabela de frequência","Variável qualitativa"],"explicacao":"Permitem ver tendências e sazonalidade."},{"id":7238,"materia":"prev","nivel":2,"enunciado":"A aposentadoria do servidor público federal efetivo é regida pelo:","opcoes":["Regime próprio de previdência","Regime geral do INSS","Seguro-desemprego","FGTS"],"explicacao":"O RGPS atende os trabalhadores da iniciativa privada."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('trib','afo','cont','adua','eco','aud','dados','prev') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
